/** A world fragment and the same vehicle UUID have one durable owner throughout a coupling change. */
public final class VehicleCouplingTransfer {
    private static final Map<WorldServer,ArrayDeque<Work>> QUEUES=new IdentityHashMap<>();
    private static final Map<WorldServer,Map<Path,Hold>> HOLDS=new IdentityHashMap<>();
    private static final Map<WorldServer,Set<UUID>> QUARANTINE=new IdentityHashMap<>();
    private static final Set<WorldServer> LOADED=Collections.newSetFromMap(new IdentityHashMap<>());
    private static final ThreadLocal<Work> VALIDATING=new ThreadLocal<>();
    private static final ThreadLocal<EntityGroundVehicle> SPAWNING=new ThreadLocal<>();
    interface Fault{void check(String stage);}
    static Fault fault;
    private static void check(String stage){if(fault!=null&&System.getProperty("vandorlabs.reprolab")!=null)fault.check(stage);}
    private static final class Work{
        final VehicleCouplingPlan plan;final EntityPlayerMP actor;final Runnable completed;final Consumer<Exception> failed;
        Hold hold;Future<?> journal;boolean journalReady,failedCallback;
        Work(EntityPlayerMP actor,VehicleCouplingPlan plan,Runnable completed,Consumer<Exception> failed){this.actor=actor;this.plan=plan;this.completed=completed;this.failed=failed;}
    }
    private static final class Hold{
        final WorldServer world;final Path file;final NBTTagCompound record;final UUID id;VehicleStructure fragment;final BlockPos origin;
        EntityGroundVehicle craft;TransferCheckpoint checkpoint;boolean recovering;final List<FrozenLink> links=new ArrayList<>();
        Hold(WorldServer world,Path file,NBTTagCompound record){this.world=world;this.file=file;this.record=record.copy();if(record.getInteger("Schema")!=1||!record.hasUniqueId("Vehicle"))throw new IllegalArgumentException("Unknown coupling journal");id=record.getUniqueId("Vehicle");validateEntity(record.getCompoundTag("Before"),id,world);validateEntity(record.getCompoundTag("After"),id,world);fragment=VehicleStructure.readDisplay(record.getCompoundTag("Fragment"));origin=BlockPos.fromLong(record.getLong("Origin"));if(fragment.cells.isEmpty())throw new IllegalArgumentException("Empty coupling journal fragment");for(VehicleStructure.Cell cell:fragment.cells){BlockPos at=origin.add(cell.pos);if(at.getY()<0||at.getY()>=world.getHeight())throw new IllegalArgumentException("Coupling journal outside world height");}}
        boolean attaching(){return record.getBoolean("Attaching");}
        boolean rolledBack(){return record.getBoolean("RolledBack");}
        boolean owns(BlockPos at){return fragment.at(at.subtract(origin))!=null;}
        boolean loaded(){for(VehicleStructure.Cell cell:fragment.cells)if(!world.isBlockLoaded(origin.add(cell.pos),false))return false;for(String name:new String[]{"Before","After"})if(!world.isBlockLoaded(position(record.getCompoundTag(name)),false))return false;return true;}
        Set<Chunk> chunks(){Set<Chunk> result=new LinkedHashSet<>();for(VehicleStructure.Cell cell:fragment.cells)result.add(world.getChunkFromBlockCoords(origin.add(cell.pos)));for(String name:new String[]{"Before","After"})result.add(world.getChunkFromBlockCoords(position(record.getCompoundTag(name))));if(craft!=null)result.add(world.getChunkFromBlockCoords(craft.getPosition()));return result;}
    }
    private static void validateEntity(NBTTagCompound tag,UUID id,WorldServer world){
        if(!tag.hasUniqueId("UUID")||!tag.getUniqueId("UUID").equals(id))throw new IllegalArgumentException("Coupling vehicle UUID mismatch");
        NBTTagList pos=tag.getTagList("Pos",6),rotation=tag.getTagList("Rotation",5);if(pos.tagCount()!=3||rotation.tagCount()!=2)throw new IllegalArgumentException("Invalid coupling entity pose");
        for(int i=0;i<3;i++){double value=pos.getDoubleAt(i);if(!Double.isFinite(value)||Math.abs(value)>30_000_128D||i==1&&(value<0||value>=world.getHeight()))throw new IllegalArgumentException("Coupling entity pose outside world");}for(int i=0;i<2;i++)if(!Float.isFinite(rotation.getFloatAt(i)))throw new IllegalArgumentException("Invalid coupling orientation");
        VehicleStructure structure=VehicleStructure.read(tag.getCompoundTag("Craft"));try{structure.encode();}catch(IOException invalid){throw new IllegalArgumentException("Coupling vehicle data exceeds save limit",invalid);}
    }
    private static boolean quarantined(WorldServer world,UUID id){Set<UUID> ids=QUARANTINE.get(world);return ids!=null&&ids.contains(id);}
    private static void quarantine(WorldServer world,NBTTagCompound record){Set<UUID> ids=QUARANTINE.computeIfAbsent(world,w->new HashSet<>());if(record.hasUniqueId("Vehicle"))ids.add(record.getUniqueId("Vehicle"));for(String name:new String[]{"Before","After"}){NBTTagCompound entity=record.getCompoundTag(name);if(entity.hasUniqueId("UUID"))ids.add(entity.getUniqueId("UUID"));}}
    private static class FrozenLink implements RedstoneChannelMember{
        final Hold hold;final TileEntity anchor=new TileEntity(){};final int channel;int level;boolean active=true;
        FrozenLink(Hold hold,int channel,int level){this.hold=hold;this.channel=channel;this.level=level;anchor.setWorld(hold.world);anchor.setPos(position(hold.record.getCompoundTag("Before")));}
        public TileEntity channelTile(){return anchor;}public boolean isChannelMemberActive(){return active;}public int getRedstoneChannel(){return channel;}public void setRedstoneChannel(int ignored){throw new UnsupportedOperationException();}public boolean hasLocalRedstoneSignal(){return level>0;}public int localSignalLevel(int ignored){return level;}public void setChannelSignal(boolean ignored){}
    }
    private static final class FrozenLatch extends FrozenLink implements RedstoneChannelLatch{
        final int index;FrozenLatch(Hold hold,int channel,int level,int index){super(hold,channel,level);this.index=index;}
        public boolean isChannelLatch(){return true;}public boolean latchOn(){return level>0;}public int latchedLevel(int ignored){return level;}public void applyLinkedLatch(boolean on){applyLinkedLevels(Collections.singletonMap(channel,on?15:0));}public void applyLinkedLevels(Map<Integer,Integer> next){int value=Math.max(0,Math.min(15,next.getOrDefault(channel,0)));if(value==level)return;level=value;int[] saved=hold.record.getIntArray("HeldLatchLevels");saved[index]=value;hold.record.setIntArray("HeldLatchLevels",saved);hold.record.setBoolean("PendingLatches",true);try{save(hold.file,hold.record);}catch(IOException unavailable){com.vandorlabs.VandorLabs.logger.error("Pending coupling latch update retained in memory; checkpoint remains blocked",unavailable);}}
    }
    private static List<RedstoneChannelMember> members(Collection<TileEntity> tiles){List<RedstoneChannelMember> result=new ArrayList<>();for(TileEntity tile:tiles){if(tile instanceof RedstoneChannelMember)result.add((RedstoneChannelMember)tile);if(tile instanceof TileEntityCockpit)result.addAll(((TileEntityCockpit)tile).controls);if(tile instanceof TileEntityAnimatedScreenSelector)for(int side=0;side<2;side++){TileEntityAnimatedScreenSelector screen=(TileEntityAnimatedScreenSelector)tile;if(screen.hasRedstoneScreen(side))result.addAll(screen.redstoneScreen(side).rows());}}return result;}
    private static void levels(Map<Integer,Integer> levels,RedstoneChannelMember member){for(int channel:member.getRedstoneChannels().toArray()){if(channel<=0)continue;int level=Math.max(0,Math.min(15,member.localSignalLevel(channel)));if(member instanceof RedstoneChannelLatch&&((RedstoneChannelLatch)member).isChannelLatch())level=Math.max(level,((RedstoneChannelLatch)member).latchedLevel(channel));if(level>0)levels.put(channel,Math.max(levels.getOrDefault(channel,0),level));}}
    private static void ensureBridge(Hold hold){if(!hold.links.isEmpty())return;int[] channels=hold.record.getIntArray("FrozenChannels"),values=hold.record.getIntArray("FrozenLevels"),latches=hold.record.getIntArray("HeldLatchChannels"),levels=hold.record.getIntArray("HeldLatchLevels");if(channels.length!=values.length||channels.length>65535||latches.length!=levels.length||latches.length>65535)throw new IllegalArgumentException("Invalid frozen coupling signal bank");for(int i=0;i<channels.length;i++){if(channels[i]<1||channels[i]>65535||values[i]<1||values[i]>15)throw new IllegalArgumentException("Invalid frozen coupling output");FrozenLink link=new FrozenLink(hold,channels[i],values[i]);hold.links.add(link);RedstoneChannels.register(link);}for(int i=0;i<latches.length;i++){if(latches[i]<1||latches[i]>65535||levels[i]<0||levels[i]>15)throw new IllegalArgumentException("Invalid held coupling latch");FrozenLink link=new FrozenLatch(hold,latches[i],levels[i],i);hold.links.add(link);RedstoneChannels.register(link);}}
    private static void collectLevels(Map<Integer,Integer> independent,Map<Integer,Integer> latches,RedstoneChannelMember source){if(source instanceof RedstoneChannelLatch&&((RedstoneChannelLatch)source).isChannelLatch()){RedstoneChannelLatch latch=(RedstoneChannelLatch)source;for(int channel:source.getRedstoneChannels().toArray())if(channel>0)latches.put(channel,Math.max(latches.getOrDefault(channel,0),Math.max(0,Math.min(15,latch.latchedLevel(channel)))));}else levels(independent,source);}
    private static void writeLevels(NBTTagCompound tag,String key,Map<Integer,Integer> map){int[] channels=new int[map.size()],levels=new int[map.size()];int i=0;for(Map.Entry<Integer,Integer> entry:map.entrySet()){channels[i]=entry.getKey();levels[i++]=entry.getValue();}tag.setIntArray(key+"Channels",channels);tag.setIntArray(key+"Levels",levels);}
    private static void removeBridge(Hold hold){for(FrozenLink link:hold.links){link.active=false;RedstoneChannels.unregister(link);}hold.links.clear();}
    private static void registerWorldSources(Hold hold){List<TileEntity> tiles=new ArrayList<>();for(VehicleStructure.Cell cell:hold.fragment.cells){TileEntity tile=hold.world.getTileEntity(hold.origin.add(cell.pos));if(tile!=null)tiles.add(tile);}for(RedstoneChannelMember source:members(tiles))RedstoneChannels.register(source);}
    private VehicleCouplingTransfer(){}
    private static Path directory(WorldServer world){return world.getSaveHandler().getWorldDirectory().toPath().resolve("data").resolve("vandorlabs-couplings-"+world.provider.getDimension());}
    public static boolean busy(EntityGroundVehicle craft){if(craft==null||!(craft.world instanceof WorldServer))return false;if(quarantined((WorldServer)craft.world,craft.getUniqueID()))return true;ArrayDeque<Work> queue=QUEUES.get(craft.world);if(queue!=null)for(Work work:queue)if(work.plan.craft==craft)return true;Map<Path,Hold> holds=HOLDS.get(craft.world);if(holds!=null)for(Hold hold:holds.values())if(hold.id.equals(craft.getUniqueID()))return true;return false;}
    public static boolean locked(World world,BlockPos pos){if(world instanceof WorldServer&&!LOADED.contains(world)){load((WorldServer)world);if(!LOADED.contains(world))return true;}Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values()){Work own=VALIDATING.get();if(own!=null&&own.hold==hold)continue;if(hold.owns(pos))return true;}ArrayDeque<Work> queue=QUEUES.get(world);if(queue!=null)for(Work work:queue)if(VALIDATING.get()!=work&&work.plan.fragment.at(pos.subtract(work.plan.fragmentOrigin))!=null)return true;return false;}
    public static void submit(EntityPlayerMP actor,VehicleCouplingPlan plan,Runnable completed,Consumer<Exception> failed){if(plan==null||actor==null||actor.world!=plan.craft.world||!(plan.craft.world instanceof WorldServer))throw new IllegalArgumentException("Invalid coupling authorization");if(busy(plan.craft))throw new IllegalArgumentException("Vehicle coupling or recovery is already in progress");WorldServer world=(WorldServer)plan.craft.world;ArrayDeque<Work> queue=QUEUES.computeIfAbsent(world,w->new ArrayDeque<>());if(queue.size()>=8)throw new IllegalArgumentException("Coupling queue is full");VehicleChests.close(plan.craft);plan.craft.setTransferInProgress(true);queue.add(new Work(actor,plan,completed==null?()->{}:completed,failed==null?e->{}:failed));}
    private static void validate(Work work)throws Exception{VALIDATING.set(work);try{work.plan.validate(work.actor);}finally{VALIDATING.remove();}}
    private static NBTTagList coordinates(double x,double y,double z){NBTTagList list=new NBTTagList();list.appendTag(new NBTTagDouble(x));list.appendTag(new NBTTagDouble(y));list.appendTag(new NBTTagDouble(z));return list;}
    private static BlockPos position(NBTTagCompound entity){NBTTagList list=entity.getTagList("Pos",6);if(list.tagCount()!=3)throw new IllegalArgumentException("Invalid coupling entity position");return new BlockPos(list.getDoubleAt(0),list.getDoubleAt(1),list.getDoubleAt(2));}
    private static NBTTagCompound after(NBTTagCompound before,VehicleCouplingPlan plan){NBTTagCompound tag=before.copy();tag.setTag("Craft",plan.after.write());tag.setTag("Pos",coordinates(plan.x,plan.y,plan.z));tag.setDouble("HoverTarget",before.getDouble("HoverTarget")+plan.y-plan.beforeY);BlockPos shift=plan.after.seat.subtract(plan.before.seat);NBTTagCompound seats=tag.getCompoundTag("OccupiedPilotSeats");for(String name:seats.getKeySet())if(seats.hasKey(name,4))seats.setLong(name,BlockPos.fromLong(seats.getLong(name)).add(shift).toLong());if(tag.hasKey("TaxiReturnSeat",4))tag.setLong("TaxiReturnSeat",BlockPos.fromLong(tag.getLong("TaxiReturnSeat")).add(shift).toLong());return tag;}
    private static Hold prepare(WorldServer world,Work work)throws Exception{
        if(world.disableLevelSaving)throw new IOException("World saving is disabled");validate(work);EntityGroundVehicle craft=work.plan.craft;craft.signals.persist();validate(work);NBTTagCompound before=craft.writeToNBT(new NBTTagCompound()),tag=new NBTTagCompound();tag.setInteger("Schema",1);tag.setUniqueId("AuthorizedActor",work.actor.getUniqueID());tag.setUniqueId("Vehicle",craft.getUniqueID());tag.setTag("Before",before);tag.setTag("After",after(before,work.plan));tag.setTag("Fragment",work.plan.fragment.write());tag.setLong("Origin",work.plan.fragmentOrigin.toLong());tag.setBoolean("Attaching",work.plan.attaching);Map<Integer,Integer> outputs=new TreeMap<>(),latches=new TreeMap<>();for(RedstoneChannelMember member:members(craft.view.tiles.values()))if(member instanceof RedstoneChannelLatch||member instanceof TileEntityRedstoneChannel||member instanceof TileEntityCockpit.Control)collectLevels(outputs,latches,member);if(work.plan.attaching){List<TileEntity> source=new ArrayList<>();for(VehicleStructure.Cell cell:work.plan.fragment.cells){TileEntity tile=world.getTileEntity(work.plan.fragmentOrigin.add(cell.pos));if(tile!=null)source.add(tile);}for(RedstoneChannelMember member:members(source))collectLevels(outputs,latches,member);}writeLevels(tag,"Frozen",outputs);writeLevels(tag,"HeldLatch",latches);Path file=directory(world).resolve(UUID.randomUUID()+".nbt");Hold hold=new Hold(world,file,tag);hold.craft=craft;return hold;
    }
    static void save(Path file,NBTTagCompound record)throws IOException{Files.createDirectories(file.getParent());Path temp=file.resolveSibling(file.getFileName()+".tmp");ByteArrayOutputStream bytes=new ByteArrayOutputStream();CompressedStreamTools.writeCompressed(record,bytes);if(bytes.size()>16*1024*1024)throw new IOException("Coupling journal exceeds 16 MiB");try(FileOutputStream out=new FileOutputStream(temp.toFile())){out.write(bytes.toByteArray());out.getFD().sync();}Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);com.vandorlabs.persistence.JournalFiles.syncDirectory(file.getParent());}
    static NBTTagCompound read(Path file)throws IOException{if(Files.size(file)>16*1024*1024)throw new IOException("Oversized coupling journal");try(InputStream in=Files.newInputStream(file)){return CompressedStreamTools.read(new DataInputStream(new java.util.zip.GZIPInputStream(in)),new NBTSizeTracker(128L*1024*1024));}}
    private static void closeContainers(Hold hold){if(hold.craft!=null)VehicleChests.close(hold.craft);net.minecraft.util.math.AxisAlignedBB area=hold.fragment.bounds.offset(hold.origin).grow(8);for(EntityPlayer player:hold.world.playerEntities)if(player.openContainer!=player.inventoryContainer&&(area.contains(player.getPositionVector())||hold.craft!=null&&player.getDistanceSq(hold.craft)<64))player.closeScreen();}
    private static void holdCraft(Hold hold){for(Entity entity:hold.world.loadedEntityList)if(entity instanceof EntityGroundVehicle&&entity.getUniqueID().equals(hold.id)){EntityGroundVehicle craft=(EntityGroundVehicle)entity;if(hold.craft!=null&&hold.craft!=craft)throw new IllegalStateException("Duplicate coupling vehicle UUID");hold.craft=craft;craft.signals.close();craft.setTransferInProgress(true);craft.ownershipBlocked=true;}}
    private static void freeze(Hold hold,Chunk only){for(VehicleStructure.Cell cell:hold.fragment.cells)if(cell.hasTileData()){BlockPos at=hold.origin.add(cell.pos);if(only!=null&&((at.getX()>>4)!=only.x||(at.getZ()>>4)!=only.z)||!hold.world.isBlockLoaded(at,false))continue;if(hold.world.getTileEntity(at)!=null)CopyWorld.freeze(hold.world,at);}}
    private static boolean full(Hold hold){return hold.fragment.matches(hold.world,hold.origin);}
    private static boolean empty(Hold hold){return CopyWorld.empty(hold.world,hold.fragment,hold.origin);}
    private static Map<Integer,Integer> latchLevels(Hold hold){int[] channels=hold.record.getIntArray("HeldLatchChannels"),values=hold.record.getIntArray("HeldLatchLevels");Map<Integer,Integer> levels=new HashMap<>();for(int i=0;i<channels.length;i++)levels.put(channels[i],values[i]);return levels;}
    private static VehicleStructure latchSnapshot(WorldServer world,VehicleStructure source,Map<Integer,Integer> levels){
        VehicleWorld view=new VehicleWorld(world,source);Set<BlockPos> changed=new HashSet<>();
        for(RedstoneChannelMember member:members(view.tiles.values()))if(member instanceof RedstoneChannelLatch&&((RedstoneChannelLatch)member).isChannelLatch()){
            RedstoneChannelLatch latch=(RedstoneChannelLatch)member;Map<Integer,Integer> next=new HashMap<>();boolean selected=false;for(int channel:member.getRedstoneChannels().toArray()){selected|=levels.containsKey(channel);next.put(channel,levels.getOrDefault(channel,latch.latchedLevel(channel)));}if(!selected)continue;TileEntity owner=member.channelTile();
            if(owner instanceof TileEntityRedstoneChannel){NBTTagCompound data=owner.writeToNBT(new NBTTagCompound());ChannelList channels=member.getRedstoneChannels();int[] saved=new int[channels.size()];List<Integer> on=new ArrayList<>();for(int i=0;i<saved.length;i++){saved[i]=next.getOrDefault(channels.get(i),0);if(saved[i]>0)on.add(channels.get(i));}data.setIntArray("LatchedLevels",saved);data.setIntArray("LatchedChannels",on.stream().mapToInt(Integer::intValue).toArray());data.setBoolean(com.vandorlabs.persistence.SaveSchema.Redstone.LOCAL_ON,!channels.isEmpty()&&on.size()==channels.size());owner.readFromNBT(data);}else latch.applyLinkedLevels(next);changed.add(owner.getPos());
        }
        List<VehicleStructure.Cell> cells=new ArrayList<>();for(VehicleStructure.Cell cell:source.cells){if(!changed.contains(cell.pos)){cells.add(cell);continue;}TileEntity tile=view.getTileEntity(cell.pos);NBTTagCompound data=tile.writeToNBT(new NBTTagCompound());net.minecraft.block.state.IBlockState state=cell.state;
            if(tile instanceof TileEntityRedstoneChannel){boolean on=((TileEntityRedstoneChannel)tile).getOutputLevel()>0;if(state.getProperties().containsKey(com.vandorlabs.blocks.BlockVandorSwitch.ON))state=state.withProperty(com.vandorlabs.blocks.BlockVandorSwitch.ON,on);else if(state.getProperties().containsKey(com.vandorlabs.blocks.BlockIndustrialLever.POWERED))state=state.withProperty(com.vandorlabs.blocks.BlockIndustrialLever.POWERED,on);}
            // Visible aggregates are derived from the per-channel latch bank, never an independent ON source.
            for(String key:new String[]{"RedstonePrimary","RedstoneSecondary"})if(data.hasKey(key,10)){NBTTagList rows=data.getCompoundTag(key).getTagList("Rows",10);for(int i=0;i<rows.tagCount();i++){NBTTagCompound row=rows.getCompoundTagAt(i);if(row.getBoolean("Pulse"))continue;int[] channels=row.getIntArray("RedstoneChannels"),saved=row.getIntArray("Levels");int max=0;boolean all=channels.length>0;for(int n=0;n<channels.length;n++){int value=n<saved.length?saved[n]:0;max=Math.max(max,value);all&=value>0;}row.setInteger("Level",max);row.setBoolean("Active",all);}}
            if(data.hasKey("CockpitControls",9)){NBTTagList controls=data.getTagList("CockpitControls",10);for(int i=0;i<controls.tagCount();i++){NBTTagCompound control=controls.getCompoundTagAt(i);if(control.getInteger("Kind")==2)continue;int[] saved=control.getIntArray("Levels");int max=0;boolean all=saved.length>0;for(int level:saved){max=Math.max(max,level);all&=level>0;}control.setInteger("Level",control.getInteger("Kind")==1?max:all?15:0);}}
            cells.add(new VehicleStructure.Cell(cell.pos,state,data));
        }
        return source.displayOnly?VehicleStructure.display(cells):new VehicleStructure(cells,source.seat,source.facing,source.gearCount);
    }
    private static void syncLatches(Hold hold)throws Exception{
        if(!hold.record.getBoolean("PendingLatches"))return;Map<Integer,Integer> levels=latchLevels(hold);VehicleStructure nextFragment=latchSnapshot(hold.world,hold.fragment,levels);boolean occupied=hold.rolledBack()?hold.attaching():!hold.attaching();
        if(occupied){List<VehicleStructure.Cell> actual=new ArrayList<>();for(VehicleStructure.Cell cell:hold.fragment.cells){BlockPos at=hold.origin.add(cell.pos);TileEntity tile=hold.world.getTileEntity(at);actual.add(new VehicleStructure.Cell(cell.pos,hold.world.getBlockState(at),tile==null?null:VehicleTileData.translated(tile.writeToNBT(new NBTTagCompound()),BlockPos.ORIGIN.subtract(hold.origin))));}if(!latchSnapshot(hold.world,VehicleStructure.display(actual),levels).write().equals(nextFragment.write()))throw new IllegalArgumentException("Coupling resources changed while applying pending latch controls");}else if(!empty(hold))throw new IllegalArgumentException("Coupling world cells changed while holding latch input");
        NBTTagCompound next=hold.record.copy();for(String key:new String[]{"Before","After"}){NBTTagCompound entity=next.getCompoundTag(key);entity.setTag("Craft",latchSnapshot(hold.world,VehicleStructure.read(entity.getCompoundTag("Craft")),levels).write());}next.setTag("Fragment",nextFragment.write());next.setBoolean("PendingLatches",true);save(hold.file,next);hold.record.merge(next);hold.fragment=nextFragment;if(hold.checkpoint!=null){hold.checkpoint.close();hold.checkpoint=null;}
        try(AutoCloseable atomic=VehicleTransfer.atomic(hold.world)){if(occupied)CopyWorld.install(hold.world,hold.fragment,hold.origin,CopyWorld.prepare(hold.world,hold.fragment,hold.origin),true);applyCraft(hold,hold.rolledBack());hold.record.setBoolean("PendingLatches",false);save(hold.file,hold.record);}
    }
    private static void requireWorld(Hold hold,boolean before){boolean occupied=before?hold.attaching():!hold.attaching();if(!(occupied?full(hold):empty(hold)))throw new IllegalArgumentException("Coupled section changed; exact ownership backup retained");}
    private static void stamp(Hold hold)throws Exception{VehicleOwnership.Update update=VehicleOwnership.prepare(hold.world,hold.id,Math.max(hold.record.getCompoundTag("Before").getLong("TransferEpoch"),hold.record.getCompoundTag("After").getLong("TransferEpoch"))+1,true);hold.record.getCompoundTag("Before").setLong("TransferEpoch",update.epoch);hold.record.getCompoundTag("After").setLong("TransferEpoch",update.epoch);save(hold.file,hold.record);update.write();update.publish(hold.world);}
    private static void applyCraft(Hold hold,boolean before)throws Exception{
        NBTTagCompound data=hold.record.getCompoundTag(before?"Before":"After").copy();VehicleStructure snapshot=VehicleStructure.read(data.getCompoundTag("Craft"));VehicleWorld view=new VehicleWorld(hold.world,snapshot);MovingBlockSupport.validate(snapshot,view);VehicleCollision collision=new VehicleCollision(view);snapshot.encode();EntityGroundVehicle craft=hold.craft;
        if(craft==null||craft.isDead){craft=new EntityGroundVehicle(hold.world);craft.setUniqueId(hold.id);hold.craft=craft;}
        craft.signals.close();craft.readFromNBT(data);if(craft.structure==null||craft.view==null||!craft.structure.write().equals(snapshot.write()))throw new IllegalStateException("Coupled vehicle cannot be installed exactly");craft.collision=collision;craft.collisionCache.reset(craft.view,collision);craft.setTransferInProgress(true);craft.ownershipBlocked=true;craft.motionX=craft.motionY=craft.motionZ=0;craft.setPosition(craft.posX,craft.posY,craft.posZ);
        if(!hold.world.loadedEntityList.contains(craft)){SPAWNING.set(craft);try{if(!hold.world.spawnEntity(craft))throw new IOException("Coupling recovery vehicle spawn was cancelled");}finally{SPAWNING.remove();}}
        // Rebase can cross a chunk boundary. Reindex without advancing gameplay before checkpointing.
        hold.world.updateEntityWithOptionalForce(craft,false);
    }
    private static void worldBefore(Hold hold){if(hold.attaching())CopyWorld.install(hold.world,hold.fragment,hold.origin,CopyWorld.prepare(hold.world,hold.fragment,hold.origin),true);else CopyWorld.clear(hold.world,hold.fragment,hold.origin);}
    private static void worldAfter(Hold hold){if(hold.attaching())CopyWorld.clear(hold.world,hold.fragment,hold.origin);else CopyWorld.install(hold.world,hold.fragment,hold.origin,CopyWorld.prepare(hold.world,hold.fragment,hold.origin),true);}
    private static void verify(Hold hold)throws Exception{requireWorld(hold,hold.rolledBack());if(hold.craft==null||hold.craft.structure==null||!hold.craft.structure.write().equals(hold.record.getCompoundTag(hold.rolledBack()?"Before":"After").getCompoundTag("Craft")))throw new IllegalArgumentException("Held vehicle changed; coupling backup retained");}
    private static void rollback(Hold hold,boolean internal)throws Exception{
        try(AutoCloseable atomic=VehicleTransfer.atomic(hold.world)){ensureBridge(hold);
        if(hold.checkpoint!=null){hold.checkpoint.close();hold.checkpoint=null;}
        if(hold.record.getBoolean("Installed"))requireWorld(hold,false);else if(!full(hold)&&!empty(hold)&&!(internal&&CopyWorld.clearOrMatches(hold.world,hold.fragment,hold.origin,true)))throw new IllegalArgumentException("Interrupted coupling section changed; backup retained");
        stamp(hold);worldBefore(hold);applyCraft(hold,true);hold.record.setBoolean("RolledBack",true);save(hold.file,hold.record);freeze(hold,null);}
    }
    private static void publish(Hold hold){boolean occupied=hold.rolledBack()?hold.attaching():!hold.attaching();if(occupied)for(VehicleStructure.Cell cell:hold.fragment.cells){CopyWorld.publish(hold.world,hold.origin.add(cell.pos));if(hold.record.hasUniqueId("AuthorizedActor"))com.vandorlabs.tiles.WorldActionAuthorization.grant(hold.world.getTileEntity(hold.origin.add(cell.pos)),hold.record.getUniqueId("AuthorizedActor"));check("publish");}if(!occupied)check("publish");}
    private static boolean finish(Hold hold)throws Exception{
        if(hold.world.disableLevelSaving)throw new IOException("World saving is disabled; coupling remains locked");
        verify(hold);check("checkpoint");if(hold.checkpoint==null)hold.checkpoint=new TransferCheckpoint(hold.world,hold.chunks());if(!hold.checkpoint.step())return false;hold.checkpoint=null;check("commit");hold.record.setBoolean("Committed",true);save(hold.file,hold.record);
        try(AutoCloseable atomic=VehicleTransfer.atomic(hold.world)){
            ensureBridge(hold);publish(hold);registerWorldSources(hold);Files.delete(hold.file);HOLDS.get(hold.world).remove(hold.file);
            try{EntityGroundVehicle craft=hold.craft;craft.ownershipBlocked=false;craft.setTransferInProgress(false);craft.signals.open();craft.signals.tick();CopyWorld.notify(hold.world,hold.fragment,hold.origin);for(EntityPlayer player:hold.world.playerEntities)if(player instanceof EntityPlayerMP&&player.getDistanceSq(craft)<256*256)VehicleNetwork.send((EntityPlayerMP)player,craft.structure,craft.getEntityId(),craft.getUniqueID(),new BlockPos(craft),false,false);}
            finally{removeBridge(hold);}
        }
        return true;
    }
    public static void tick(WorldServer world){load(world);if(!LOADED.contains(world))return;ArrayDeque<Work> queue=QUEUES.get(world);if(queue==null||queue.isEmpty())return;Work work=queue.peek();if(!TransferCoordinator.acquire(world,work))return;
        try{if(work.hold==null){work.hold=prepare(world,work);NBTTagCompound stable=work.hold.record.copy();Path file=work.hold.file;work.journal=TransferJournalIO.submit(()->save(file,stable));return;}
            if(!work.journalReady){if(!work.journal.isDone())return;work.journal.get();validate(work);HOLDS.computeIfAbsent(world,w->new LinkedHashMap<>()).put(work.hold.file,work.hold);work.journalReady=true;check("journal");try(AutoCloseable atomic=VehicleTransfer.atomic(world)){ensureBridge(work.hold);validate(work);closeContainers(work.hold);holdCraft(work.hold);freeze(work.hold,null);stamp(work.hold);check("world");worldAfter(work.hold);check("entity");applyCraft(work.hold,false);verify(work.hold);work.hold.record.setBoolean("Installed",true);save(work.hold.file,work.hold.record);check("install");stamp(work.hold);work.hold.craft.transferEpoch=work.hold.record.getCompoundTag("After").getLong("TransferEpoch");}return;}
            syncLatches(work.hold);if(finish(work.hold)){TransferCoordinator.release(world,work);queue.remove(work);try{work.completed.run();}catch(RuntimeException callback){com.vandorlabs.VandorLabs.logger.warn("Coupling completion callback failed after durable ownership",callback);}}
        }catch(Exception failure){if(work.journalReady&&work.hold!=null&&Files.exists(work.hold.file)){try{syncLatches(work.hold);if(!work.hold.record.getBoolean("Committed")){rollback(work.hold,true);}freeze(work.hold,null);holdCraft(work.hold);}catch(Exception blocked){failure.addSuppressed(blocked);}work.hold.recovering=false;}else{if(work.hold!=null&&work.journal!=null&&work.journal.isDone())try{Files.deleteIfExists(work.hold.file);}catch(IOException cleanup){failure.addSuppressed(cleanup);}work.plan.craft.setTransferInProgress(false);}TransferCoordinator.release(world,work);queue.remove(work);work.failedCallback=true;try{work.failed.accept(failure);}catch(RuntimeException callback){com.vandorlabs.VandorLabs.logger.warn("Coupling failure callback unavailable",callback);}}
    }
    public static void load(WorldServer world){if(!LOADED.add(world))return;Path dir=directory(world);try{TransferJournalIO.barrier();}catch(Exception unavailable){LOADED.remove(world);com.vandorlabs.VandorLabs.logger.error("Coupling journal disk worker unavailable; transfers remain locked",unavailable);return;}if(!Files.isDirectory(dir))return;Set<UUID> seen=new HashSet<>();try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"*.nbt")){int count=0;for(Path file:files){if(++count>32)throw new IOException("Too many pending coupling journals");NBTTagCompound record=null;try{record=read(file);Hold hold=new Hold(world,file,record);if(!seen.add(hold.id))quarantine(world,record);HOLDS.computeIfAbsent(world,w->new LinkedHashMap<>()).put(file,hold);try(AutoCloseable atomic=VehicleTransfer.atomic(world)){ensureBridge(hold);}}catch(Exception error){if(record!=null)quarantine(world,record);com.vandorlabs.VandorLabs.logger.error("Coupling journal retained but unavailable {}",file.getFileName(),error);}}}catch(IOException error){com.vandorlabs.VandorLabs.logger.error("Coupling recovery journals unavailable",error);}}
    public static boolean joining(EntityGroundVehicle craft){if(SPAWNING.get()==craft)return false;if(!(craft.world instanceof WorldServer))return false;WorldServer world=(WorldServer)craft.world;load(world);if(!LOADED.contains(world)||quarantined(world,craft.getUniqueID()))return true;Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values())if(hold.id.equals(craft.getUniqueID()))return true;return false;}
    public static void beforeTick(WorldServer world){load(world);for(Entity entity:world.loadedEntityList)if(entity instanceof EntityGroundVehicle&&quarantined(world,entity.getUniqueID())){EntityGroundVehicle craft=(EntityGroundVehicle)entity;VehicleChests.close(craft);craft.signals.close();craft.setTransferInProgress(true);craft.ownershipBlocked=true;}Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values()){holdCraft(hold);closeContainers(hold);freeze(hold,null);}}
    public static void chunkLoaded(Chunk chunk){if(!(chunk.getWorld() instanceof WorldServer))return;WorldServer world=(WorldServer)chunk.getWorld();load(world);Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values())freeze(hold,chunk);}
    public static void recover(WorldServer world){load(world);Map<Path,Hold> holds=HOLDS.get(world);if(holds==null)return;Set<Hold> active=Collections.newSetFromMap(new IdentityHashMap<>());ArrayDeque<Work> queue=QUEUES.get(world);if(queue!=null)for(Work work:queue)if(work.hold!=null)active.add(work.hold);for(Hold hold:new ArrayList<>(holds.values())){if(quarantined(world,hold.id)||active.contains(hold)||!hold.loaded()||world.disableLevelSaving||!TransferCoordinator.acquire(world,hold))continue;try{holdCraft(hold);freeze(hold,null);syncLatches(hold);if(!hold.recovering){if(!hold.record.getBoolean("Committed")&&!hold.rolledBack())rollback(hold,false);else if(hold.craft==null){stamp(hold);applyCraft(hold,hold.rolledBack());}hold.recovering=true;}finish(hold);}catch(Exception blocked){if(hold.checkpoint!=null){hold.checkpoint.close();hold.checkpoint=null;}try{freeze(hold,null);holdCraft(hold);}catch(Exception preserve){blocked.addSuppressed(preserve);}com.vandorlabs.VandorLabs.logger.warn("Coupling recovery remains locked {}",hold.file.getFileName(),blocked);}finally{TransferCoordinator.release(world,hold);}}}
    public static void unload(WorldServer world){ArrayDeque<Work> queue=QUEUES.remove(world);if(queue!=null)for(Work work:queue)TransferCoordinator.release(world,work);Map<Path,Hold> holds=HOLDS.remove(world);if(holds!=null)for(Hold hold:holds.values()){if(hold.checkpoint!=null)hold.checkpoint.close();removeBridge(hold);TransferCoordinator.release(world,hold);}LOADED.remove(world);QUARANTINE.remove(world);}
    public static int pendingCount(WorldServer world){Map<Path,Hold> holds=HOLDS.get(world);return (holds==null?0:holds.size())+(QUARANTINE.containsKey(world)?QUARANTINE.get(world).size():0);}
    public static void drainForChecks(WorldServer world)throws Exception{long deadline=System.nanoTime()+65_000_000_000L;while(QUEUES.containsKey(world)&&!QUEUES.get(world).isEmpty()&&System.nanoTime()<deadline){beforeTick(world);tick(world);Thread.sleep(25);}if(QUEUES.containsKey(world)&&!QUEUES.get(world).isEmpty())throw new IllegalStateException("Coupling queue did not finish its checkpoint");}
}
